function AutoTextarea({ value, onChange }: { value: string; onChange: (v: string) => void }) {
  const ref = useRef<HTMLTextAreaElement>(null);

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reset height to get accurate scrollHeight
    el.style.height = 'auto';
    el.style.height = `${el.scrollHeight}px`;
  }, [value]);

  return (
    <textarea
      ref={ref}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      className="w-full resize-none overflow-hidden"
    />
  );
}

function Tooltip({ trigger, children }: { trigger: React.ReactNode; children: React.ReactNode }) {
  const triggerRef = useRef<HTMLDivElement>(null);
  const [coords, setCoords] = useState({ top: 0, left: 0 });

  useLayoutEffect(() => {
    const rect = triggerRef.current?.getBoundingClientRect();
    if (rect) {
      setCoords({
        top: rect.bottom + window.scrollY + 8,
        left: rect.left + window.scrollX,
      });
    }
  }, []);

  return (
    <>
      <span ref={triggerRef}>{trigger}</span>
      <div
        style={{ position: 'absolute', top: coords.top, left: coords.left }}
        className="rounded bg-gray-900 px-2 py-1 text-white"
      >
        {children}
      </div>
    </>
  );
}

import { useEffect, useLayoutEffect } from 'react';

const useIsomorphicLayoutEffect =
  typeof window !== 'undefined' ? useLayoutEffect : useEffect;

function useMeasure(ref: RefObject<HTMLElement>) {
  const [bounds, setBounds] = useState({ width: 0, height: 0 });

  useIsomorphicLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    setBounds({
      width: el.offsetWidth,
      height: el.offsetHeight,
    });
  }, [ref]);

  return bounds;
}

